package com.witchersbestiary.client.fist;
import com.witchersbestiary.fist.*;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.text.Text;
public final class TournamentScreen extends Screen {
 public static Text hud(){return view!=null&&view.fighting()&&view.category()>=0?t("hud",t(TournamentProgress.Category.values()[view.category()].name().toLowerCase()),view.round()+1,TournamentProgress.Category.values()[view.category()].rounds):null;}
 public static boolean available(){return view!=null&&view.category()>=0;}
 private static TournamentPackets.View view;private int selected;
 public TournamentScreen(){super(t("title"));if(view!=null&&view.category()>=0)selected=view.category();}
 static Text t(String key,Object... args){return Text.translatable("tournament.witchersbestiary."+key,args);}
 public static void initialize(){net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.registerGlobalReceiver(TournamentPackets.View.ID,(v,c)->c.client().execute(()->{view=v;if(v.open()){if(c.client().currentScreen instanceof TournamentScreen screen)screen.clearAndInit();else c.client().setScreen(new TournamentScreen());}else if(c.client().currentScreen instanceof TournamentScreen)c.client().setScreen(null);}));net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents.DISCONNECT.register((h,c)->view=null);}
 private void send(int action){if(view!=null)net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new TournamentPackets.Control(view.token(),action));}
 @Override protected void init(){if(view==null)return;int x=width/2-150,y=height/2-110;for(int i=0;i<3;i++){final int c=i;var button=addDrawableChild(ButtonWidget.builder(t(TournamentProgress.Category.values()[i].name().toLowerCase()),b->{selected=c;clearAndInit();}).dimensions(x+i*101,y,98,20).build());button.active=view.category()<0;}
 var enter=addDrawableChild(ButtonWidget.builder(t("enter"),b->send(selected)).dimensions(x,y+196,96,20).build());enter.active=view.category()<0&&(selected==0||(view.titles()&(1<<(selected-1)))!=0);
 var next=addDrawableChild(ButtonWidget.builder(t("continue"),b->send(3)).dimensions(x+101,y+196,98,20).build());next.active=view.category()>=0&&!view.fighting();var leave=addDrawableChild(ButtonWidget.builder(t("abandon"),b->send(4)).dimensions(x+203,y+196,97,20).build());leave.active=view.category()>=0;
 }
 @Override public boolean shouldPause(){return false;}
 @Override public void render(DrawContext d,int mx,int my,float delta){int x=width/2-150,y=height/2-110;d.fill(x-8,y-22,x+308,y+224,0xf025201c);super.render(d,mx,my,delta);d.drawCenteredTextWithShadow(textRenderer,title,width/2,y-16,0xffe6ca9a);if(view==null)return;var category=TournamentProgress.Category.values()[view.category()<0?selected:view.category()];d.drawTextWithShadow(textRenderer,t("reward",category.rounds,category.reward),x,y+28,0xffe6ca9a);for(int i=0;i<category.rounds;i++){boolean active=view.category()==category.ordinal();boolean history=view.category()<0&&view.lastCategory()==category.ordinal();int done=active?view.round():history?view.lastRound():0;String state=i<done?"won":history&&!view.lastWon()&&i==done?"lost":"waiting";d.drawTextWithShadow(textRenderer,t("bracket",i+1,t("tier"+category.tier(i)),t(state)),x,y+48+i*17,0xffead6b2);}int row=0;for(int i=0;i<3;i++)if((view.titles()&(1<<i))!=0)d.drawTextWithShadow(textRenderer,t("title"+i),x,y+139+row++*12,0xffffd66c);d.drawTextWithShadow(textRenderer,t("rules"),x,y+181,0xffb6ac9d);}
}
